from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
text=(ROOT/'04_analysis/run_climate_campaign_v3.py').read_text()
text=text.replace("SITE=sys.argv[1]\nassert SITE in ['Padova','Bolzano','Roma','Palermo']\nRUN=ROOT/f'05_simulations/climate_campaign_v3/{SITE}'", "import argparse,re\nparser=argparse.ArgumentParser()\nparser.add_argument('SITE',choices=['Padova','Bolzano','Roma','Palermo'])\nparser.add_argument('--campaign',required=True)\nparser.add_argument('--replay-only-seeded',action='store_true')\nargs=parser.parse_args()\nSITE=args.SITE\nassert re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]*',args.campaign) and '..' not in args.campaign\nRUN=ROOT/'05_simulations'/args.campaign/SITE\nassert RUN.resolve().is_relative_to((ROOT/'05_simulations').resolve())")
text=text.replace("    transitions=json.loads", "    if (RUN/'completion_manifest.json').exists() or any(RUN.glob('*_hourly.csv')):\n        raise FileExistsError(f'Refusing to overwrite existing simulation outputs: {RUN}')\n    launch_cwd=os.getcwd()\n    weather_audit=ROOT/'05_simulations/weather_forcing_v4/weather_forcing_audit.json'\n    assert json.loads(weather_audit.read_text())['pass']\n    transitions=json.loads",1)
text=text.replace("['simulation_protocol.md','simulation_protocol_v2_addendum.md','correction_protocol_v3.md']", "['simulation_protocol.md','simulation_protocol_v2_addendum.md','correction_protocol_v3.md','weather_correction_protocol_v4.md']")
text=text.replace("    audit=json.loads", "    (RUN/'ir_sky_forcing.py').write_bytes((ROOT/'04_analysis/ir_sky_forcing.py').read_bytes())\n    (RUN/'weather_forcing_audit_pre_run.json').write_bytes(weather_audit.read_bytes())\n    audit=json.loads",1)
text=text.replace("    design['correction']='", "    design['campaign']=args.campaign\n    if args.replay_only_seeded: design['cases']=[['seeded',168]]\n    design['replay_only_seeded']=args.replay_only_seeded\n    design['weather_correction']='horizontal IR effective sky temperature; native annual mean delta retained'\n    design['correction']='",1)
text=text.replace("'command':f'{sys.executable} -B {__file__}'", "'command':f'& \\\"{sys.executable}\\\" -B \\\"{__file__}\\\" {SITE} --campaign {args.campaign}'+(' --replay-only-seeded' if args.replay_only_seeded else ''),'argv':sys.argv,'launch_cwd':launch_cwd,'campaign':args.campaign,'weather_correction_sha256':sha(RUN/'ir_sky_forcing.py'),'weather_protocol_sha256':sha(RUN/'weather_correction_protocol_v4.md'),'forcing_audit_sha256':sha(RUN/'weather_forcing_audit_pre_run.json')")
text=text.replace("    from single_commit_1c import solve_1c_single_commit", "    from single_commit_1c import solve_1c_single_commit\n    from ir_sky_forcing import apply_ir_sky_forcing,verify_native_longwave")
text=text.replace("    write(RUN/'frozen_manifest.json',frozen)", "    import subprocess\n    command_args=[sys.executable,'-B',str(Path(__file__).resolve()),SITE,'--campaign',args.campaign]+(['--replay-only-seeded'] if args.replay_only_seeded else [])\n    frozen['command']='& '+subprocess.list2cmdline(command_args)\n    frozen['command_argv']=command_args\n    write(RUN/'frozen_manifest.json',frozen)")
text=text.replace("    print('WEATHER_INDEX'", "    apply_ir_sky_forcing(weather,WX,RUN,SITE,weather_audit)\n    print('WEATHER_INDEX'",1)
text=text.replace("        z.calculate_zone_loads_ISO13790(weather)", "        z.calculate_zone_loads_ISO13790(weather)")
text=text.replace("        z=zone(lower)", "        z=zone(lower)\n        verify_native_longwave(z,weather,RUN,name)")
text=text.replace("    base=pd.read_csv", "    if args.replay_only_seeded:\n        frozen.update({'status':'complete_replay_seeded_only','summary_sha256':sha(RUN/'summary.csv'),'scientific_sample':False})\n        write(RUN/'completion_manifest.json',frozen)\n        return\n    base=pd.read_csv",1)
# Preserve original manifests; old exception handler must not write inside an
# existing immutable directory when refusing an overwrite.
text=text.replace("        (RUN/'failure.txt').write_text(traceback.format_exc(),encoding='utf-8')", "        if not (RUN/'completion_manifest.json').exists():\n            (RUN/'failure.txt').write_text(traceback.format_exc(),encoding='utf-8')")
(ROOT/'04_analysis/run_climate_campaign_v4.py').write_text(text)
print('Prepared non-destructive v4 interface with explicit SITE/campaign and replay mode')
